package org.apache.commons.lang3.math;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_1_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Hexadecimal string with leading zeros and a significant digit greater than '7'
        String hexString = "0x0000000000000080";
        try {
            Number result = NumberUtils.createNumber(hexString);
            // Expecting a BigInteger because the number is too large for a Long
            assertTrue("Expected instance of BigInteger", result instanceof java.math.BigInteger);
        } catch (NumberFormatException e) {
            fail("NumberFormatException was thrown: " + e.getMessage());
        }
    }
}

